-- Differentiated original reading mini-texts and task-specific assessments on central ideas.
-- 66 published Grade1-3 "الفكرة الرئيسة" lessons across 22 countries, 198 OPTIONAL activities.
-- The original mini-text for every activity lives in content.originalText; never assume country source texts are identical.
-- This batch does not verify equivalence to any country's current ministerial curriculum.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='90s';
CREATE TEMP TABLE g123_mainidea_198_templates ON COMMIT DROP AS
SELECT grade::int,activity_order::int,activity_type::text,title::text,section::text,prompt::text,content::jsonb,answer::jsonb
FROM jsonb_to_recordset($ideas$[{"grade":1,"activity_order":4,"activity_type":"fill_blank","title":"أقرأ التفصيل وأكمله","section":"practice","prompt":"ماذا كان يسقي فهد كل صباح في القصة؟","content":{"origin":"DADYOOM_G123_MAIN_IDEA_ORIGINAL_198_20261030","originalText":"«زرعَ فهدٌ نبتةً صغيرةً في الحديقة. كان يسقيها كل صباح، ويضعها قرب الضوء. بعد أيام ظهرت أوراق خضراء. فرح فهد لأنه اعتنى بالنبتة.» الفكرة الرئيسة تجمع ما يدور حوله النص كله، أما ظهور الأوراق فهو تفصيل يدعمها.","items":[{"sentence":"كان فهد يسقي ___ كل صباح.","options":["النبتة","السيارة","الحقيبة"]}],"scope":"supplementary-original-text"},"answer":{"answers":["النبتة"]}},{"grade":1,"activity_order":5,"activity_type":"matching","title":"أصل الفكرة بدليلها","section":"practice","prompt":"اقرأ النص الإثرائي، ثم صِل الجملة بما تمثله من فكرة رئيسة أو تفصيل أو دليل.","content":{"origin":"DADYOOM_G123_MAIN_IDEA_ORIGINAL_198_20261030","originalText":"«زرعَ فهدٌ نبتةً صغيرةً في الحديقة. كان يسقيها كل صباح، ويضعها قرب الضوء. بعد أيام ظهرت أوراق خضراء. فرح فهد لأنه اعتنى بالنبتة.» الفكرة الرئيسة تجمع ما يدور حوله النص كله، أما ظهور الأوراق فهو تفصيل يدعمها.","left":["يسقي الطفل شجرة كل صباح فتنمو.","تقرأ مريم قصة قبل النوم فتتعلم كلمات.","يرتب حسن أوراق الصف في سلة النظافة."],"right":["الاهتمام بالنبات","القراءة والتعلم","المحافظة على نظافة الصف"],"scope":"supplementary-original-text"},"answer":{"pairs":[{"left":"يسقي الطفل شجرة كل صباح فتنمو.","right":"الاهتمام بالنبات"},{"left":"تقرأ مريم قصة قبل النوم فتتعلم كلمات.","right":"القراءة والتعلم"},{"left":"يرتب حسن أوراق الصف في سلة النظافة.","right":"المحافظة على نظافة الصف"}]}},{"grade":1,"activity_order":6,"activity_type":"multiple_choice","title":"أستنتج الفكرة الرئيسة","section":"assessment","prompt":"ما الفكرة الرئيسة لقصة فهد والنبتة؟","content":{"origin":"DADYOOM_G123_MAIN_IDEA_ORIGINAL_198_20261030","originalText":"«زرعَ فهدٌ نبتةً صغيرةً في الحديقة. كان يسقيها كل صباح، ويضعها قرب الضوء. بعد أيام ظهرت أوراق خضراء. فرح فهد لأنه اعتنى بالنبتة.» الفكرة الرئيسة تجمع ما يدور حوله النص كله، أما ظهور الأوراق فهو تفصيل يدعمها.","options":["لون الأوراق فقط","العناية بالنبات تساعده على النمو","شراء لعبة جديدة"],"scope":"supplementary-original-text"},"answer":{"correct":"العناية بالنبات تساعده على النمو"}},{"grade":2,"activity_order":4,"activity_type":"fill_blank","title":"أقرأ التفصيل وأكمله","section":"practice","prompt":"ما المشكلة التي لاحظتها آمنة في ساحة المدرسة؟","content":{"origin":"DADYOOM_G123_MAIN_IDEA_ORIGINAL_198_20261030","originalText":"«لاحظت آمنة أن حنفية الماء تبقى مفتوحة بعد استراحة المدرسة. تحدثت مع زميلاتها، وصنعن بطاقة تذكير بإغلاق الحنفية. بعد أسبوع أصبح الأطفال أكثر حرصًا على الماء. تعلّم الفريق أن التعاون والسلوك اليومي يقللان الهدر.» اختر الفكرة التي تشمل الموقف والجهد والنتيجة، لا تفصيلًا واحدًا.","items":[{"sentence":"لاحظت آمنة أن حنفية الماء تبقى ___.","options":["مفتوحة","مغلقة","مكسورة"]}],"scope":"supplementary-original-text"},"answer":{"answers":["مفتوحة"]}},{"grade":2,"activity_order":5,"activity_type":"matching","title":"أصل الفكرة بدليلها","section":"practice","prompt":"اقرأ النص الإثرائي، ثم صِل الجملة بما تمثله من فكرة رئيسة أو تفصيل أو دليل.","content":{"origin":"DADYOOM_G123_MAIN_IDEA_ORIGINAL_198_20261030","originalText":"«لاحظت آمنة أن حنفية الماء تبقى مفتوحة بعد استراحة المدرسة. تحدثت مع زميلاتها، وصنعن بطاقة تذكير بإغلاق الحنفية. بعد أسبوع أصبح الأطفال أكثر حرصًا على الماء. تعلّم الفريق أن التعاون والسلوك اليومي يقللان الهدر.» اختر الفكرة التي تشمل الموقف والجهد والنتيجة، لا تفصيلًا واحدًا.","left":["الحفاظ على الماء مسؤولية يشترك فيها الطلاب.","صنعت الطالبات بطاقة تذكير بإغلاق الحنفية.","تحدث النص عن التعاون لتقليل هدر الماء."],"right":["تفصيل يشرح كيف جرى الحل","فكرة رئيسة تشمل المشكلة والحل","صياغة عامة لقيمة المحافظة على الماء"],"scope":"supplementary-original-text"},"answer":{"pairs":[{"left":"الحفاظ على الماء مسؤولية يشترك فيها الطلاب.","right":"صياغة عامة لقيمة المحافظة على الماء"},{"left":"صنعت الطالبات بطاقة تذكير بإغلاق الحنفية.","right":"تفصيل يشرح كيف جرى الحل"},{"left":"تحدث النص عن التعاون لتقليل هدر الماء.","right":"فكرة رئيسة تشمل المشكلة والحل"}]}},{"grade":2,"activity_order":6,"activity_type":"multiple_choice","title":"أستنتج الفكرة الرئيسة","section":"assessment","prompt":"أي عنوان يلخّص قصة آمنة دون الاكتفاء بتفصيل واحد؟","content":{"origin":"DADYOOM_G123_MAIN_IDEA_ORIGINAL_198_20261030","originalText":"«لاحظت آمنة أن حنفية الماء تبقى مفتوحة بعد استراحة المدرسة. تحدثت مع زميلاتها، وصنعن بطاقة تذكير بإغلاق الحنفية. بعد أسبوع أصبح الأطفال أكثر حرصًا على الماء. تعلّم الفريق أن التعاون والسلوك اليومي يقللان الهدر.» اختر الفكرة التي تشمل الموقف والجهد والنتيجة، لا تفصيلًا واحدًا.","options":["بطاقة ملونة على الحائط","تعاون الطلاب لترشيد الماء","وقت الاستراحة فقط"],"scope":"supplementary-original-text"},"answer":{"correct":"تعاون الطلاب لترشيد الماء"}},{"grade":3,"activity_order":4,"activity_type":"fill_blank","title":"أقرأ التفصيل وأكمله","section":"practice","prompt":"ما الدليل الذي استخدمه الفريق للحكم على نجاح تغيير رف المكتبة؟","content":{"origin":"DADYOOM_G123_MAIN_IDEA_ORIGINAL_198_20261030","originalText":"«في مكتبة المدرسة كانت الكتب الجديدة على رف مرتفع يصعب على التلاميذ الصغار الوصول إليه. سأل الفريق الطلاب، ثم نقل المشرف الكتب إلى رف آمن مناسب. راقب الفريق عدد استعارات الكتب قبل التغيير وبعده، ولاحظ زيادته. لم يكن نقل الرف غاية في ذاته؛ بل وسيلة لتيسير القراءة. تظهر القصة كيف يساعد تحديد المشكلة ثم اختبار الحل على تحسين خدمة المكتبة.» استخرج فكرة تشمل المشكلة والحل والدليل، وميز بينها وبين تفصيل مذكور.","items":[{"sentence":"قارن الفريق عدد ___ قبل تغيير الرف وبعده.","options":["استعارات الكتب","نوافذ الصف","لوحات المرور"]}],"scope":"supplementary-original-text"},"answer":{"answers":["استعارات الكتب"]}},{"grade":3,"activity_order":5,"activity_type":"matching","title":"أصل الفكرة بدليلها","section":"practice","prompt":"اقرأ النص الإثرائي، ثم صِل الجملة بما تمثله من فكرة رئيسة أو تفصيل أو دليل.","content":{"origin":"DADYOOM_G123_MAIN_IDEA_ORIGINAL_198_20261030","originalText":"«في مكتبة المدرسة كانت الكتب الجديدة على رف مرتفع يصعب على التلاميذ الصغار الوصول إليه. سأل الفريق الطلاب، ثم نقل المشرف الكتب إلى رف آمن مناسب. راقب الفريق عدد استعارات الكتب قبل التغيير وبعده، ولاحظ زيادته. لم يكن نقل الرف غاية في ذاته؛ بل وسيلة لتيسير القراءة. تظهر القصة كيف يساعد تحديد المشكلة ثم اختبار الحل على تحسين خدمة المكتبة.» استخرج فكرة تشمل المشكلة والحل والدليل، وميز بينها وبين تفصيل مذكور.","left":["جعل الكتب في متناول الصغار يزيد فرص القراءة.","ازدادت استعارات الكتب بعد نقل الرف.","وُضعت الكتب على رف آمن مناسب."],"right":["نتيجة تدعم الفكرة الرئيسة","حل عملي تفصيلي للمشكلة","فكرة شاملة عن سهولة الوصول والقراءة"],"scope":"supplementary-original-text"},"answer":{"pairs":[{"left":"جعل الكتب في متناول الصغار يزيد فرص القراءة.","right":"فكرة شاملة عن سهولة الوصول والقراءة"},{"left":"ازدادت استعارات الكتب بعد نقل الرف.","right":"نتيجة تدعم الفكرة الرئيسة"},{"left":"وُضعت الكتب على رف آمن مناسب.","right":"حل عملي تفصيلي للمشكلة"}]}},{"grade":3,"activity_order":6,"activity_type":"multiple_choice","title":"أستنتج الفكرة الرئيسة","section":"assessment","prompt":"لماذا تعد عبارة «تحديد المشكلة واختبار أثر الحل يحسّن المكتبة» فكرة رئيسة؟","content":{"origin":"DADYOOM_G123_MAIN_IDEA_ORIGINAL_198_20261030","originalText":"«في مكتبة المدرسة كانت الكتب الجديدة على رف مرتفع يصعب على التلاميذ الصغار الوصول إليه. سأل الفريق الطلاب، ثم نقل المشرف الكتب إلى رف آمن مناسب. راقب الفريق عدد استعارات الكتب قبل التغيير وبعده، ولاحظ زيادته. لم يكن نقل الرف غاية في ذاته؛ بل وسيلة لتيسير القراءة. تظهر القصة كيف يساعد تحديد المشكلة ثم اختبار الحل على تحسين خدمة المكتبة.» استخرج فكرة تشمل المشكلة والحل والدليل، وميز بينها وبين تفصيل مذكور.","options":["لأنها تغطي المشكلة والحل ونتيجته المدعومة بالدليل","لأنها تذكر لون الرف وحده","لأنها لا ترتبط بأحداث القصة"],"scope":"supplementary-original-text"},"answer":{"correct":"لأنها تغطي المشكلة والحل ونتيجته المدعومة بالدليل"}}]$ideas$::jsonb)
AS x(grade int,activity_order int,activity_type text,title text,section text,prompt text,content jsonb,answer jsonb);
DO $safe$
DECLARE eligible int;history_count int;inserted int;
BEGIN
IF (SELECT count(*) FROM pg_temp.g123_mainidea_198_templates)<>9 OR
(SELECT count(DISTINCT (grade,activity_order)) FROM pg_temp.g123_mainidea_198_templates)<>9 OR
EXISTS(SELECT 1 FROM pg_temp.g123_mainidea_198_templates WHERE activity_type IS NULL OR answer IS NULL OR content IS NULL OR length(content->>'originalText')<140)
THEN RAISE EXCEPTION 'Incomplete authored main idea activity templates'; END IF;
WITH lesson_check AS (
 SELECT l.id,l.content,count(a.id) FILTER(WHERE a.is_published) n,
 count(DISTINCT a.activity_order) positions,max(a.activity_order) max_pos
 FROM public.lessons l JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
 LEFT JOIN public.lesson_activities a ON a.lesson_id=l.id
 WHERE l.title='الفكرة الرئيسة' AND l.status='published' AND g.grade_number BETWEEN 1 AND 3
 GROUP BY l.id,l.content)
SELECT count(*) INTO eligible FROM lesson_check WHERE n=3 AND positions=3 AND max_pos=3
AND content LIKE '%الفكرة%' AND (content LIKE '%النص%' OR content LIKE '%القراءة%');
IF eligible<>66 THEN RAISE EXCEPTION 'Expected 66 lesson IDs with three activities: %',eligible; END IF;
SELECT count(*) INTO history_count FROM public.lessons l
JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
WHERE l.title='الفكرة الرئيسة' AND l.status='published' AND g.grade_number BETWEEN 1 AND 3
AND (EXISTS(SELECT 1 FROM public.student_lesson_progress p WHERE p.lesson_id=l.id)
OR EXISTS(SELECT 1 FROM public.lesson_activity_attempts at JOIN public.lesson_activities a ON a.id=at.activity_id WHERE a.lesson_id=l.id)
OR EXISTS(SELECT 1 FROM public.question_attempts at JOIN public.questions q ON q.id=at.question_id WHERE q.lesson_id=l.id));
IF history_count<>0 THEN RAISE EXCEPTION 'Learner history changed, abort: %',history_count; END IF;
IF EXISTS(SELECT 1 FROM public.lesson_activities a WHERE a.content->>'origin'='DADYOOM_G123_MAIN_IDEA_ORIGINAL_198_20261030')
THEN RAISE EXCEPTION 'Do not insert duplicate main-idea batch'; END IF;
INSERT INTO public.lesson_activities
(lesson_id,title,activity_type,instructions,content,activity_order,points,is_published,section,prompt,answer,is_required)
SELECT l.id,t.title,t.activity_type,'اقرأ النص الإثرائي الأصلي داخل النشاط ثم طبّق مهارة الفكرة الرئيسة.',
 t.content,t.activity_order,5,true,t.section,t.prompt,t.answer,false
 FROM public.lessons l JOIN public.units u ON u.id=l.unit_id JOIN public.grades g ON g.id=u.grade_id
 JOIN pg_temp.g123_mainidea_198_templates t ON t.grade=g.grade_number
 WHERE l.title='الفكرة الرئيسة' AND l.status='published' AND g.grade_number BETWEEN 1 AND 3
 AND l.content LIKE '%الفكرة%' AND (l.content LIKE '%النص%' OR l.content LIKE '%القراءة%');
GET DIAGNOSTICS inserted=ROW_COUNT;
IF inserted<>198 THEN RAISE EXCEPTION 'Atomic rollback: inserted only % instead of 198',inserted; END IF;
RAISE NOTICE 'DADYOOM_G123_MAINIDEA_GRADED_ORIGINAL_ACTIVITIES=%',inserted;
END $safe$;
COMMIT;
